package lk.repairdesk.api.config; import lk.repairdesk.api.domain.*; import lk.repairdesk.api.repository.UserRepository; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import org.springframework.security.crypto.password.PasswordEncoder; @Configuration public class DemoDataConfig { @Bean CommandLineRunner seed(UserRepository users,PasswordEncoder encoder,@Value("${app.seed-demo}")boolean enabled){return args->{if(!enabled)return;create(users,encoder,"Admin","admin@repairdesk.lk","Admin@123",Role.ADMIN);create(users,encoder,"Manager","manager@repairdesk.lk","Manager@123",Role.MANAGER);create(users,encoder,"Technician","technician@repairdesk.lk","Technician@123",Role.TECHNICIAN);create(users,encoder,"Customer","customer@repairdesk.lk","Customer@123",Role.CUSTOMER);};} private void create(UserRepository r,PasswordEncoder e,String n,String mail,String p,Role role){if(r.existsByEmailIgnoreCase(mail))return;var u=new User();u.setName(n);u.setEmail(mail);u.setPassword(e.encode(p));u.setRole(role);r.save(u);} }